import json
from fractions import Fraction as F
from math import gcd

c = F(20, -24) - (2 + -3)
# f(x) = 1/16 x^4 + 1/8 x^2 + 0 x + 1 - c x^3  (low -> high)
f = [F(1), F(0), F(1, 8), -c, F(1, 16)]
k = [f[i] * i for i in range(1, len(f))]  # derivative

def trim(p):
    while p and p[-1] == 0:
        p = p[:-1]
    return p

def divroot(p, r):
    # synthetic division by (x - r); p low->high
    n = len(p) - 1
    hi = p[::-1]
    out = [hi[0]]
    for a in hi[1:]:
        out.append(a + out[-1] * r)
    rem = out[-1]
    q = out[:-1][::-1]
    return q, rem

def ev(p, r):
    return sum(a * r**i for i, a in enumerate(p))

def divisors(n):
    n = abs(n)
    return [d for d in range(1, n + 1) if n % d == 0]

p = trim(k)
lead = p[-1]
roots = {}
while len(p) > 1:
    # clear denominators
    den = 1
    for a in p:
        den = den * a.denominator // gcd(den, a.denominator)
    ip = [int(a * den) for a in p]
    if ip[0] == 0:
        r = F(0)
    else:
        found = None
        for num in divisors(ip[0]):
            for d in divisors(ip[-1]):
                for s in (1, -1):
                    cand = F(s * num, d)
                    if ev(p, cand) == 0:
                        found = cand
                        break
                if found is not None: break
            if found is not None: break
        if found is None:
            break
        r = found
    q, rem = divroot(p, r)
    assert rem == 0
    roots[r] = roots.get(r, 0) + 1
    p = q

def fmt_root(r, m):
    if r == 0:
        base = "s"
    elif r > 0:
        base = f"(s - {r})"
    else:
        base = f"(s + {-r})"
    return base + (f"**{m}" if m > 1 else "")

parts = [fmt_root(r, m) for r, m in sorted(roots.items())]
if len(p) > 1:
    parts.append("(" + " + ".join(f"{a}*s^{i}" for i, a in enumerate(p)) + ")")
    const = F(1)
else:
    const = p[0] if p else F(1)
# const multiplies remaining
if const.denominator == 1:
    cs = str(const.numerator)
else:
    cs = f"{const.numerator}/{const.denominator}"
ans = (cs + "*" if const != 1 else "") + "*".join(parts)
# tidy: put constant as fraction in denominator form
if const != 1 and const.numerator == 1:
    ans = "*".join(parts) + f"/{const.denominator}"
    ans = ans.replace("*", "*", 1)

print(json.dumps({
    "final_answer": ans,
    "evidence": {
        "c": str(c),
        "k_coeffs_low_to_high": [str(a) for a in trim(k)],
        "roots": {str(r): m for r, m in roots.items()},
        "leading_const": str(const),
    }
}))
